// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract GestionAuditeurs {

    address public ownerContrat; 

    struct Auditeur {
        string nom;
        string prenom;
        string numeroAuditeur;    
        string entreprise;
        address adresseEthereum;
        bool estActif;         
    }

    mapping(address => Auditeur) public auditeurs;
    mapping(string => address) private auditeurParNumero; 
    address[] public listeAdressesAuditeursActifs;
    mapping(address => uint) private auditeurIndexInList; // pour la supression

    event AuditeurEnregistre(address indexed auditeurAddress, string numeroAuditeur, string nom, string entreprise, uint timestamp);
    event AuditeurModifie(address indexed auditeurAddress, bool estActif, uint timestamp);
    event AuditeurSupprime(address indexed auditeurAddress, uint timestamp); // Si suppression complète

    modifier onlyOwnerContrat() {
        require(msg.sender == ownerContrat, "Reserve au proprietaire du contrat.");
        _;
    }

    modifier auditeurExiste(address _auditeurAddress) {
        require(auditeurs[_auditeurAddress].adresseEthereum != address(0), "L auditeur n existe pas.");
        _;
    }

    modifier auditeurNExistePas(address _auditeurAddress) {
        require(auditeurs[_auditeurAddress].adresseEthereum == address(0), "L auditeur existe deja a cette adresse.");
        _;
    }

    constructor() {
        ownerContrat = msg.sender;
    }

    function enregistrerAuditeur(
        address _auditeurAddress,
        string calldata _nom,
        string calldata _prenom,
        string calldata _numeroAuditeur,
        string calldata _entreprise
    ) external onlyOwnerContrat auditeurNExistePas(_auditeurAddress) {
        require(_auditeurAddress != address(0), "Adresse auditeur invalide.");
        require(bytes(_nom).length > 0, "Nom requis.");
        require(bytes(_prenom).length > 0, "Prenom requis.");
        require(bytes(_numeroAuditeur).length > 0, "Numero Auditeur requis.");
        require(auditeurParNumero[_numeroAuditeur] == address(0), "Ce numero d auditeur est deja utilise.");

        auditeurs[_auditeurAddress] = Auditeur({
            nom: _nom,
            prenom: _prenom,
            numeroAuditeur: _numeroAuditeur,
            entreprise: _entreprise,
            adresseEthereum: _auditeurAddress,
            estActif: true
        });

        auditeurParNumero[_numeroAuditeur] = _auditeurAddress;

        auditeurIndexInList[_auditeurAddress] = listeAdressesAuditeursActifs.length;
        listeAdressesAuditeursActifs.push(_auditeurAddress);

        emit AuditeurEnregistre(_auditeurAddress, _numeroAuditeur, _nom, _entreprise, block.timestamp);
    }

    function desactiverAuditeur(address _auditeurAddress) external onlyOwnerContrat auditeurExiste(_auditeurAddress) {
        require(auditeurs[_auditeurAddress].estActif, "L auditeur est deja inactif.");
        auditeurs[_auditeurAddress].estActif = false;

        // Supprimer de la liste des actifs
        uint indexASupprimer = auditeurIndexInList[_auditeurAddress];
        address dernierAuditeurActif = listeAdressesAuditeursActifs[listeAdressesAuditeursActifs.length - 1];
        listeAdressesAuditeursActifs[indexASupprimer] = dernierAuditeurActif;
        auditeurIndexInList[dernierAuditeurActif] = indexASupprimer;
        listeAdressesAuditeursActifs.pop();
        delete auditeurIndexInList[_auditeurAddress];

        emit AuditeurModifie(_auditeurAddress, false, block.timestamp);
    }

    function reactiverAuditeur(address _auditeurAddress) external onlyOwnerContrat auditeurExiste(_auditeurAddress) {
        require(!auditeurs[_auditeurAddress].estActif, "L auditeur est deja actif.");
        auditeurs[_auditeurAddress].estActif = true;

        // Ajouter à la liste des actifs
        auditeurIndexInList[_auditeurAddress] = listeAdressesAuditeursActifs.length;
        listeAdressesAuditeursActifs.push(_auditeurAddress);

        emit AuditeurModifie(_auditeurAddress, true, block.timestamp);
    }

    // Option pour supprimer complètement un auditeur (plus drastique que désactiver)
    function supprimerAuditeur(address _auditeurAddress) external onlyOwnerContrat auditeurExiste(_auditeurAddress) {
        if (auditeurs[_auditeurAddress].estActif) {
            // S'il est actif, le retirer de la liste des actifs d'abord
            uint indexASupprimer = auditeurIndexInList[_auditeurAddress];
            address dernierAuditeurActif = listeAdressesAuditeursActifs[listeAdressesAuditeursActifs.length - 1];
            listeAdressesAuditeursActifs[indexASupprimer] = dernierAuditeurActif;
            auditeurIndexInList[dernierAuditeurActif] = indexASupprimer;
            listeAdressesAuditeursActifs.pop();
            delete auditeurIndexInList[_auditeurAddress];
        }

        delete auditeurParNumero[auditeurs[_auditeurAddress].numeroAuditeur];
        delete auditeurs[_auditeurAddress];

        emit AuditeurSupprime(_auditeurAddress, block.timestamp);
    }

    function getAuditeurInfo(address _auditeurAddress) external view auditeurExiste(_auditeurAddress) returns (Auditeur memory) {
        return auditeurs[_auditeurAddress];
    }

    function getListeAuditeursActifs() external view returns (address[] memory) {
        return listeAdressesAuditeursActifs;
    }

    function estAuditeurActif(address _auditeurAddress) external view returns (bool) {
        return auditeurs[_auditeurAddress].adresseEthereum != address(0) && auditeurs[_auditeurAddress].estActif;
    }
}

contracts/GestionDroitsPatient.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract GestionDroitsPatient {

    address public ownerContrat; // Patient initial ou administrateur des patients

    struct Patient {
        string nom;
        string prenom;
        address adresseEthereum; // Adresse blockchain du patient
        string adressePhysique;  // Adresse de résidence du patient
        bool estEnregistre;      // Pour marquer si le patient est actif/enregistré
    }

    enum StatutErreur {
        Soumise,
        EnCoursDeValidation, 
        Validee,
        Invalidee,
        Resolue
    }

    struct ErreurMedicale {
        uint idErreur;
        address idHopital;       // Adresse du contrat de l'hopital
        address idPatient;       // Adresse Ethereum du patient
        uint date;               // Timestamp de la contestation
        string description;
        StatutErreur statut;
    }

    mapping(address => Patient) public patients;
    address[] public listeAdressesPatients; 
    mapping(address => uint) private patientIndexInList;

    uint public prochainIdErreur;
    ErreurMedicale[] public toutesLesErreurs;

    mapping(address => uint[]) public erreursSoumisesParHopital; 
    mapping(address => uint[]) public erreursSoumisesParPatient; 

    event PatientEnregistre(address indexed patientAddress, string nom, string prenom, bool estOwnerContrat, uint timestamp);
    event PatientRevoque(address indexed patientAddress, uint timestamp);
    event ErreurMedicaleContestee(uint indexed idErreur, address indexed idHopital, address indexed idPatient, string description, uint timestamp);
    event StatutErreurModifie(uint indexed idErreur, StatutErreur nouveauStatut, uint timestamp);

    modifier onlyOwnerContrat() {
        require(msg.sender == ownerContrat, "Action reservee au proprietaire du contrat.");
        _;
    }

    modifier onlyPatientEnregistre() {
        require(patients[msg.sender].estEnregistre, "Action reservee aux patients enregistres.");
        _;
    }

    modifier patientNonEnregistre(address _patientAddress) {
        require(!patients[_patientAddress].estEnregistre, "Patient deja enregistre.");
        _;
    }

    modifier patientExiste(address _patientAddress) {
        require(patients[_patientAddress].estEnregistre, "Patient non enregistre.");
        _;
    }

    constructor() {
        ownerContrat = msg.sender; 
    }

    function _ajouterPatient(address _adresseEthereumPatient, string calldata _nom, string calldata _prenom, string calldata _adressePhysique) private patientNonEnregistre(_adresseEthereumPatient) {
        require(_adresseEthereumPatient != address(0), "Adresse patient invalide.");
        require(bytes(_nom).length > 0, "Nom requis.");
        require(bytes(_prenom).length > 0, "Prenom requis.");

        patients[_adresseEthereumPatient] = Patient({
            nom: _nom,
            prenom: _prenom,
            adresseEthereum: _adresseEthereumPatient,
            adressePhysique: _adressePhysique,
            estEnregistre: true
        });

        patientIndexInList[_adresseEthereumPatient] = listeAdressesPatients.length;
        listeAdressesPatients.push(_adresseEthereumPatient);

        bool estOwner = (_adresseEthereumPatient == ownerContrat);
        emit PatientEnregistre(_adresseEthereumPatient, _nom, _prenom, estOwner, block.timestamp);
    }

    function enregistrerPatient(string calldata _nom, string calldata _prenom, string calldata _adressePhysique) external {
        _ajouterPatient(msg.sender, _nom, _prenom, _adressePhysique);
    }

    function ajouterPatientParOwner(address _adresseEthereumPatient, string calldata _nom, string calldata _prenom, string calldata _adressePhysique) external onlyOwnerContrat {
        _ajouterPatient(_adresseEthereumPatient, _nom, _prenom, _adressePhysique);
    }

    function revoquerPatient(address _patientAddress) external onlyOwnerContrat patientExiste(_patientAddress) {
        require(_patientAddress != ownerContrat, "L owner du contrat ne peut pas etre revoque lui-meme.");

        uint indexASupprimer = patientIndexInList[_patientAddress];
        if (listeAdressesPatients.length > 0) { // Sûreté, même si patientExiste devrait le garantir
            address dernierPatientDansListe = listeAdressesPatients[listeAdressesPatients.length - 1];
            if (_patientAddress != dernierPatientDansListe) {
                 listeAdressesPatients[indexASupprimer] = dernierPatientDansListe; 
                 patientIndexInList[dernierPatientDansListe] = indexASupprimer;
            }
            listeAdressesPatients.pop();
        }

        patients[_patientAddress].estEnregistre = false; 
        delete patientIndexInList[_patientAddress];

        emit PatientRevoque(_patientAddress, block.timestamp);
    }

    function contesterErreur(address _idHopital, string calldata _description) external onlyPatientEnregistre {
        require(_idHopital != address(0), "ID Hopital invalide.");
        require(bytes(_description).length > 0, "Description requise.");

        uint erreurId = prochainIdErreur;
        toutesLesErreurs.push(ErreurMedicale({
            idErreur: erreurId,
            idHopital: _idHopital,
            idPatient: msg.sender,
            date: block.timestamp,
            description: _description,
            statut: StatutErreur.Soumise
        }));

        erreursSoumisesParHopital[_idHopital].push(erreurId);
        erreursSoumisesParPatient[msg.sender].push(erreurId);

        prochainIdErreur++;

        emit ErreurMedicaleContestee(erreurId, _idHopital, msg.sender, _description, block.timestamp);
    }

    function getErreursMedicalesParHopital(address _idHopital) external view returns (ErreurMedicale[] memory) {
        uint[] memory idsErreurs = erreursSoumisesParHopital[_idHopital];
        ErreurMedicale[] memory erreursResultat = new ErreurMedicale[](idsErreurs.length);

        for (uint i = 0; i < idsErreurs.length; i++) {
            if (idsErreurs[i] < toutesLesErreurs.length) {
                erreursResultat[i] = toutesLesErreurs[idsErreurs[i]];
            }
        }
        return erreursResultat;
    }

    function getErreursValideesParHopital(address _idHopital) external view returns (ErreurMedicale[] memory) {
        uint[] memory idsErreursPourHopital = erreursSoumisesParHopital[_idHopital];
        ErreurMedicale[] memory erreursValideesTemporaire = new ErreurMedicale[](idsErreursPourHopital.length);
        uint compteurValidees = 0;

        for (uint i = 0; i < idsErreursPourHopital.length; i++) {
            uint erreurId = idsErreursPourHopital[i];
            if (erreurId < toutesLesErreurs.length && toutesLesErreurs[erreurId].statut == StatutErreur.Validee) {
                erreursValideesTemporaire[compteurValidees] = toutesLesErreurs[erreurId];
                compteurValidees++;
            }
        }

        ErreurMedicale[] memory resultatFinal = new ErreurMedicale[](compteurValidees);
        for (uint i = 0; i < compteurValidees; i++) {
            resultatFinal[i] = erreursValideesTemporaire[i];
        }
        return resultatFinal;
    }

    function getErreursMedicalesParPatient(address _idPatient) external view patientExiste(_idPatient) returns (ErreurMedicale[] memory) {
        uint[] memory idsErreurs = erreursSoumisesParPatient[_idPatient];
        ErreurMedicale[] memory erreursResultat = new ErreurMedicale[](idsErreurs.length);

        for (uint i = 0; i < idsErreurs.length; i++) {
            if (idsErreurs[i] < toutesLesErreurs.length) {
                erreursResultat[i] = toutesLesErreurs[idsErreurs[i]];
            }
        }
        return erreursResultat;
    }

    function getPatientInfo(address _patientAddress) external view patientExiste(_patientAddress) returns (Patient memory) {
        return patients[_patientAddress];
    }

    function getListePatients() external view returns (address[] memory) {
        return listeAdressesPatients;
    }

    function modifierStatutErreur(uint _idErreur, StatutErreur _nouveauStatut) external onlyOwnerContrat { 
        require(_idErreur < toutesLesErreurs.length, "ID Erreur invalide.");
        toutesLesErreurs[_idErreur].statut = _nouveauStatut;
        emit StatutErreurModifie(_idErreur, _nouveauStatut, block.timestamp);
    }
}

contracts/ManagerHopital.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract ManagerHopital {

    address public owner;
    address public auditeurAddress;

    enum EtatHopital {
        Actif,
        Suspendu
    }

    struct Hopital {
        address idHopital;
        string nom;
        string adressePhysique;
        int score;
        EtatHopital etat;
        uint contestationsValideesCount;
        int[] historiqueDesScores;
    }

    mapping(address => Hopital) public hopitaux;
    mapping(address => bool) public estEnregistre;
    address[] public listeHopitauxIds;
    mapping(address => uint) private hopitalIndexInList;

    event HopitalEnregistre(address indexed idHopital, string nom, string adressePhysique, uint timestamp);
    event HopitalSupprime(address indexed idHopital, uint timestamp);
    event HopitalSuspendu(address indexed idHopital, uint timestamp);
    event ScoreMisAJour(address indexed idHopital, int nouveauScore, int ancienScore, string raison, uint timestamp);
    event AuditeurModifie(address indexed nouvelAuditeur, address indexed ancienAuditeur, uint timestamp);

    modifier onlyOwner() {
        require(msg.sender == owner, "Reserve au proprietaire du contrat");
        _;
    }

    modifier onlyAuditeur() {
        require(msg.sender == auditeurAddress, "Reserve a l auditeur");
        _;
    }

    modifier hopitalDoitExister(address _idHopital) {
        require(estEnregistre[_idHopital], "L hopital n est pas enregistre");
        _;
    }

    modifier hopitalNeDoitPasExister(address _idHopital) {
        require(!estEnregistre[_idHopital], "L hopital est deja enregistre");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function setAuditeur(address _nouvelAuditeur) external onlyOwner {
        require(_nouvelAuditeur != address(0), "L adresse de l auditeur ne peut pas etre nulle");
        address ancienAuditeur = auditeurAddress;
        auditeurAddress = _nouvelAuditeur;
        emit AuditeurModifie(_nouvelAuditeur, ancienAuditeur, block.timestamp);
    }

    function enregistrerHopital(string calldata _nom, string calldata _adressePhysique) external hopitalNeDoitPasExister(msg.sender) {

        // juste pour ontroler les champ 
        require(bytes(_nom).length > 0, "Le nom ne peut pas etre vide");
        require(bytes(_adressePhysique).length > 0, "L adresse physique ne peut pas etre vide");

        hopitaux[msg.sender] = Hopital({
            idHopital: msg.sender,
            nom: _nom,
            adressePhysique: _adressePhysique,
            score: 0,
            etat: EtatHopital.Actif,
            contestationsValideesCount: 0,
            historiqueDesScores: new int[](0) // Initialise avec un tableau vide
        });
        hopitaux[msg.sender].historiqueDesScores.push(0); // Ajoute le score initial à l'historique

        estEnregistre[msg.sender] = true;

        //on donne un ticket pour garder la position
        hopitalIndexInList[msg.sender] = listeHopitauxIds.length;
        listeHopitauxIds.push(msg.sender);

        emit HopitalEnregistre(msg.sender, _nom, _adressePhysique, block.timestamp);
    }

    function supprimerHopitalParOwner(address _idHopital) external onlyOwner hopitalDoitExister(_idHopital) {
        uint indexASupprimer = hopitalIndexInList[_idHopital];
        address dernierHopitalDansListe = listeHopitauxIds[listeHopitauxIds.length - 1];

        // rempalce l'element à sup par le dernier élement 
        listeHopitauxIds[indexASupprimer] = dernierHopitalDansListe;
        // Met à jour l'index du dernier élément (qui a été déplacé)
        hopitalIndexInList[dernierHopitalDansListe] = indexASupprimer;

        // Supprime le dernier élément (qui est maintenant soit l'élément à supprimer, soit un duplicata)
        listeHopitauxIds.pop();

        delete hopitaux[_idHopital];
        delete estEnregistre[_idHopital];
        delete hopitalIndexInList[_idHopital];

        emit HopitalSupprime(_idHopital, block.timestamp);
    }

    function mettreAJourScore(address _idHopital, bool _contestationValidee) external onlyAuditeur hopitalDoitExister(_idHopital) {
        Hopital storage hopital = hopitaux[_idHopital];

        int ancienScore = hopital.score;
        string memory raison;

        if (_contestationValidee) {
            hopital.score -= 1;
            hopital.contestationsValideesCount += 1;
            raison = "Contestation validee";

            // on rempalce notre fonction susprendreHopital par ce bloc 
            if (hopital.contestationsValideesCount > 5 && hopital.etat == EtatHopital.Actif) {
                hopital.etat = EtatHopital.Suspendu;
                emit HopitalSuspendu(_idHopital, block.timestamp);
            }
        } else {
            hopital.score += 1;
            raison = "Contestation invalidee";
        }

        hopital.historiqueDesScores.push(hopital.score);
        emit ScoreMisAJour(_idHopital, hopital.score, ancienScore, raison, block.timestamp);
    }

    function getHopitalInfo(address _idHopital) external view hopitalDoitExister(_idHopital) returns (Hopital memory) {
        return hopitaux[_idHopital];
    }

    function getHistoriqueScore(address _idHopital) external view hopitalDoitExister(_idHopital) returns (int[] memory) {
        return hopitaux[_idHopital].historiqueDesScores;
    }

    function getListeHopitaux() external view returns (address[] memory) {
        return listeHopitauxIds;
    }

}

